from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books: set[str] = set()
        # book_id -> (user, borrow_date)
        self.borrowed_books: dict[str, tuple[str, date]] = {}
        # user -> total unpaid fines
        self.user_fines: dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            # Also register the book if not explicitly added beforehand,
            # or handle according to general library usage.
            self.books.add(book_id)

        if book_id in self.borrowed_books:
            raise ValueError(f"Book '{book_id}' is currently borrowed.")

        self.borrowed_books[book_id] = (user, day)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        if book_id not in self.borrowed_books:
            raise ValueError(f"Book '{book_id}' is not currently borrowed.")

        borrower, borrow_day = self.borrowed_books[book_id]
        if borrower != user:
            raise ValueError(f"Book '{book_id}' was not borrowed by user '{user}'.")

        due_date = borrow_day + timedelta(days=self.loan_days)
        delay_days = 0

        # Count days of delay strictly after due_date up to and including 'day',
        # excluding weekends (Saturday = 5, Sunday = 6).
        current = due_date + timedelta(days=1)
        while current <= day:
            if current.weekday() < 5:  # Monday through Friday
                delay_days += 1
            current += timedelta(days=1)

        fine = delay_days * self.daily_fine
        self.user_fines[user] = self.user_fines.get(user, 0.0) + fine
        del self.borrowed_books[book_id]

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.user_fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self.user_fines[user] = 0.0
```

